    solution: '在我的小说/我的剧本页面进入时按当前类型预加载对应编辑器模块；作品卡片在鼠标进入、按下或键盘聚焦时也触发预加载，点击时再兜底触发一次，不改变原有作品选择和标签打开逻辑。',
    prevention: '体量较大的主工作区页面不要只等点击后懒加载；入口列表、卡片悬停和键盘聚焦都应提前预加载目标页面，减少外壳状态和实际页面渲染之间的视觉时间差。',
