    solution: '在 electron/main.cjs 的窗口状态常量之后补回 let mainWindow = null，让主窗口引用在 createWindow、关闭回调和 IPC 处理之间共享；同时修正 launch-xinyuexia.mjs 的旧 Electron 进程匹配，按真实命令行路径清理。',
    prevention: '以后精简 Electron 主进程时，先跑 npm.cmd run check:electron 和 npm.cmd run check:launcher，再用月下PC版.vbs 做一次真实启动验证，并确认旧 Electron 主进程会被替换。',
    keywords: ['月下PC版.vbs', 'Electron', 'mainWindow', 'ReferenceError', 'launcher.log', 'electron-dev.log', 'Stop-Process'],
