    cause: 'ConfirmDialog 虽然设置了 z-[300]，但它按普通 React 子树渲染，没有 portal 到 document.body；当父级页面或其他 portal 弹窗形成新的层级上下文时，确认弹窗会被脑洞回收站的 portal 层压住。',
    solution: 'ConfirmDialog 改为使用 createPortal 渲染到 document.body，让确认弹窗始终位于全局浮层栈中，z-[300] 能正确压过回收站 z-[260]。',
    prevention: '通用确认弹窗、二次确认弹窗这类“弹窗上的弹窗”必须进入全局 portal 层，不能依赖调用方所在 DOM 层级。',
